// State change:
// <ul><li>A</li><li>B</li></ul>
// ↓ re-render
// <ul><li>B</li><li>A</li></ul>

// Without keys: React sees position 0 changed (A→B),
// position 1 changed (B→A) → 2 mutations.
// With keys: React matches key="a" and key="b",
// reorders pointers → minimal work.

function Counter({ step = 1, label }) { // props: configured by parent
  const [count, setCount] = useState(0); // state: owned here
  return (
    <button onClick={() => setCount(c => c + step)}>
      {label}: {count}
    </button>
  );
}

