function Banner({ user, error }) {
  if (error) return <Alert type="error">{error}</Alert>;
  if (!user) return null;

  return user.isAdmin ? (
    <AdminPanel user={user} />
  ) : (
    <>
      Welcome back{user.unread > 0 && <Badge count={user.unread} />}
    </>
  );
}

// Class version spread over 3 methods:
class Chat extends React.Component {
  componentDidMount() { subscribe(this.props.room); }
  componentDidUpdate(prev) {
    if (prev.room !== this.props.room) {
      unsubscribe(prev.room); subscribe(this.props.room);
    }
  }
  componentWillUnmount() { unsubscribe(this.props.room); }
}

// Same concern as one effect:
useEffect(() => {
  const conn = subscribe(room);
  return () => unsubscribe(conn);
}, [room]);

const ThemeContext = createContext<'light' | 'dark'>('light');

<ThemeContext.Provider value={theme}>
  <Layout /> {/* middle layers no longer need theme */}
</ThemeContext.Provider>

function Button() {
  const theme = useContext(ThemeContext);
  return <button className={theme}>Go</button>;
}
